// LEA-160: sentences that are played when OpenAI cannot speak (the connection has just dropped). They are recorded in
// advance, in every assistant voice, as the phone line's own format (μ-law 8 kHz, base64), so they need no connection to
// anyone. Generated by `npm run fallback-audio` (src/scripts/make-fallback-audio.ts); the texts are in that script.
// RULE: a new voice (VOICE_GENDER in persona.ts) or a changed sentence means running that script again;
// tests/fallback-audio.test.ts fails until every voice has all its recordings.
import { FALLBACK_CLIPS } from "./fallback-audio-data";
import { DEFAULT_VOICE_BY_GENDER, VOICE_GENDER } from "./persona";

export type ClipKind = "wait" | "apology";

/**
 * Voices whose sentences are NOT recorded yet. Empty since LEA-167: all four ElevenLabs voices are recorded. A new voice may be
 * listed here only until `npm run fallback-audio` has recorded it (the test insists on removing it then).
 * MUST BE EMPTY before the engine goes to production (see docs/features/call-ending.md).
 */
export const VOICES_WITHOUT_CLIPS_YET: string[] = [];

/** The recorded sentence in this voice and language, or null when there is none (a browser test call has no phone format). */
export function fallbackClip(kind: ClipKind, language: "cs" | "en", voice: string): string | null {
  const clips = FALLBACK_CLIPS[voice] ?? FALLBACK_CLIPS[DEFAULT_VOICE_BY_GENDER[VOICE_GENDER[voice] ?? "female"]];
  const clip = clips?.[language]?.[kind] ?? "";
  return clip ? clip : null;
}
